function Search(nums: int[], target: int) -> int {
  let lo = 0;
  let hi = nums.length() - 1;
  while (lo <= hi) {
    let mid = (lo + hi) / 2;
    let v = nums[mid];
    if (v == target) {
      return mid;
    }
    if (v < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}
